/// Filesystem operations for Miri.
///
/// Provides file and directory operations through a capability class.
/// Error handling uses the `FsError` enum.
///
/// Example:
///     use system.fs
///     let fs = Fs()
///     match fs.read_file("/tmp/data.txt")
///         Result.Ok(contents): println(contents)
///         Result.Err(e): println("error")

use system.result
use system.string

/// Represents a filesystem operation error.
@non_exhaustive
public enum FsError
    NotFound(String)
    PermissionDenied(String)
    AlreadyExists(String)
    NotADirectory(String)
    InvalidData(String)
    Other(String)

/// Filesystem capability class. Acquire a handle with `let fs = Fs()` to access filesystem operations.
public class Fs

    runtime "core" fn miri_rt_fs_status() int
    runtime "core" fn miri_rt_fs_error_message() String
    runtime "core" fn miri_rt_fs_exists(path String) int
    runtime "core" fn miri_rt_fs_read_file(path String) String
    runtime "core" fn miri_rt_fs_write_file(path String, contents String) int
    runtime "core" fn miri_rt_fs_append_file(path String, contents String) int
    runtime "core" fn miri_rt_fs_list_dir(path String) [String]
    runtime "core" fn miri_rt_fs_create_dir(path String) int
    runtime "core" fn miri_rt_fs_delete(path String) int
    runtime "core" fn miri_rt_fs_cwd() String

    /// Checks whether a file or directory exists at the given path.
    /// Returns true if exists, false if not. Never fails.
    ///
    /// Example:
    ///     let fs = Fs()
    ///     if fs.exists("/tmp/data.txt"): println("found")
    public fn exists(path String) bool
        return miri_rt_fs_exists(path) == 1

    /// Reads the entire contents of a file into a string.
    /// Non-UTF-8 content returns Err(InvalidData(path)).
    /// An empty file returns Ok(""), not an error.
    ///
    /// Example:
    ///     let fs = Fs()
    ///     match fs.read_file("/tmp/data.txt")
    ///         Result.Ok(contents): println(contents)
    ///         Result.Err(e): println("error")
    public fn read_file(path String) Result<String, FsError>
        let contents = miri_rt_fs_read_file(path)
        let status = miri_rt_fs_status()
        match status
            0: Result.Ok(contents)
            1: Result.Err(FsError.NotFound(path))
            2: Result.Err(FsError.PermissionDenied(path))
            4: Result.Err(FsError.NotADirectory(path))
            5: Result.Err(FsError.InvalidData(path))
            default: Result.Err(FsError.Other(miri_rt_fs_error_message()))

    /// Writes the given contents to a file, truncating if it exists.
    /// Creates the file if it does not exist.
    /// Returns Ok(n) where n is the number of bytes written.
    ///
    /// Example:
    ///     let fs = Fs()
    ///     match fs.write_file("/tmp/output.txt", "Hello")
    ///         Result.Ok(n): println(f"wrote {n} bytes")
    ///         Result.Err(e): println("error")
    public fn write_file(path String, contents String) Result<int, FsError>
        let bytes_written = miri_rt_fs_write_file(path, contents)
        let status = miri_rt_fs_status()
        match status
            0: Result.Ok(bytes_written)
            1: Result.Err(FsError.NotFound(path))
            2: Result.Err(FsError.PermissionDenied(path))
            4: Result.Err(FsError.NotADirectory(path))
            default: Result.Err(FsError.Other(miri_rt_fs_error_message()))

    /// Appends the given contents to a file, creating it if it doesn't exist.
    /// Returns Ok(n) where n is the number of bytes written.
    ///
    /// Example:
    ///     let fs = Fs()
    ///     match fs.append_file("/tmp/log.txt", "line\n")
    ///         Result.Ok(n): println(f"appended {n} bytes")
    ///         Result.Err(e): println("error")
    public fn append_file(path String, contents String) Result<int, FsError>
        let bytes_written = miri_rt_fs_append_file(path, contents)
        let status = miri_rt_fs_status()
        match status
            0: Result.Ok(bytes_written)
            1: Result.Err(FsError.NotFound(path))
            2: Result.Err(FsError.PermissionDenied(path))
            4: Result.Err(FsError.NotADirectory(path))
            default: Result.Err(FsError.Other(miri_rt_fs_error_message()))

    /// Lists the entries (file and directory names) in a directory.
    /// Returns Ok([names]) containing the basename of each entry.
    /// The list is unordered.
    ///
    /// Note: Due to a compiler-level gap in reference-counting semantics for Result-wrapped
    /// list payloads, the returned list and its string elements may not be freed when the
    /// Result is destructed. This causes memory to leak if list_dir results are accumulated
    /// across multiple calls. This is a compiler issue, not an Fs bug, and will be fixed
    /// when Result<[T], E> deallocation is properly implemented.
    ///
    /// Example:
    ///     let fs = Fs()
    ///     match fs.list_dir("/tmp")
    ///         Result.Ok(entries): for e in entries: println(e)
    ///         Result.Err(e): println("error")
    public fn list_dir(path String) Result<[String], FsError>
        let entries = miri_rt_fs_list_dir(path)
        let status = miri_rt_fs_status()
        match status
            0: Result.Ok(entries)
            1: Result.Err(FsError.NotFound(path))
            2: Result.Err(FsError.PermissionDenied(path))
            4: Result.Err(FsError.NotADirectory(path))
            default: Result.Err(FsError.Other(miri_rt_fs_error_message()))

    /// Creates a directory at the given path, creating missing parents as needed.
    /// Idempotent: if the directory already exists, returns Ok(false).
    /// Returns Ok(true) if newly created, Ok(false) if already existed.
    ///
    /// Example:
    ///     let fs = Fs()
    ///     match fs.create_dir("/tmp/mydir")
    ///         Result.Ok(was_new): println(f"created: {was_new}")
    ///         Result.Err(e): println("error")
    public fn create_dir(path String) Result<bool, FsError>
        let result = miri_rt_fs_create_dir(path)
        let status = miri_rt_fs_status()
        match status
            0: Result.Ok(result == 1)
            1: Result.Err(FsError.NotFound(path))
            2: Result.Err(FsError.PermissionDenied(path))
            3: Result.Err(FsError.AlreadyExists(path))
            default: Result.Err(FsError.Other(miri_rt_fs_error_message()))

    /// Deletes a regular file at the given path.
    /// Does not delete directories.
    /// Returns Ok(true) on success; there is no soft "nothing was deleted" outcome.
    /// Failures surface as Err with a status code, so do not confuse the bool with
    /// indicating whether a file existed to delete — that distinction is in the error path.
    ///
    /// Example:
    ///     let fs = Fs()
    ///     match fs.delete("/tmp/data.txt")
    ///         Result.Ok(_): println("deleted")
    ///         Result.Err(e): println("error")
    public fn delete(path String) Result<bool, FsError>
        let result = miri_rt_fs_delete(path)
        let status = miri_rt_fs_status()
        match status
            0: Result.Ok(result == 1)
            1: Result.Err(FsError.NotFound(path))
            2: Result.Err(FsError.PermissionDenied(path))
            4: Result.Err(FsError.NotADirectory(path))
            default: Result.Err(FsError.Other(miri_rt_fs_error_message()))

    /// Returns the current working directory as an absolute path.
    ///
    /// Example:
    ///     let fs = Fs()
    ///     match fs.cwd()
    ///         Result.Ok(dir): println(dir)
    ///         Result.Err(e): println("error")
    public fn cwd() Result<String, FsError>
        let dir = miri_rt_fs_cwd()
        let status = miri_rt_fs_status()
        match status
            0: Result.Ok(dir)
            default: Result.Err(FsError.Other(miri_rt_fs_error_message()))

// SPDX-License-Identifier: Apache-2.0
// Copyright (c) Viacheslav Shynkarenko

/// Environment variables and command-line arguments for Miri.
///
/// Provides access to environment variables through the `Env` capability class
/// and to command-line arguments through `Args`, which implements
/// `Iterable<String>` so it works directly in a `for` loop.
///
/// This module holds two capability classes rather than one primary type: they
/// share a single concern (the process's view of its environment) and splitting
/// them would put one class in a file of its own with no other content.
///
/// Example:
///     use system.os
///     let env = Env()
///     match env.get("PATH")
///         Some(value): println(value)
///         None: println("PATH not set")
///     let args = Args()
///     for arg in args
///         println(arg)

use system.ops
use system.result

/// Represents an environment variable operation error.
@non_exhaustive
public enum EnvError
    InvalidName(String)
    InvalidValue(String)
    Other(String)

/// Environment variable capability class. Acquire a handle with `let env = Env()`.
public class Env

    runtime "core" fn miri_rt_env_has(name String) int
    runtime "core" fn miri_rt_env_get(name String) String
    runtime "core" fn miri_rt_env_set(name String, value String) int
    runtime "core" fn miri_rt_env_status() int
    runtime "core" fn miri_rt_env_error_message() String

    /// Returns the value of an environment variable, or None if it is not set.
    ///
    /// A variable set to the empty string returns Some(""), which is distinct
    /// from an unset variable returning None.
    ///
    /// Note: the returned string is not released when the Option is destructed,
    /// so memory grows if results are read in a loop. This is a compiler-level gap
    /// in releasing a managed payload held inside an Option, not an Env bug; a
    /// plain function returning `String?` leaks the same way.
    ///
    /// Example:
    ///     let env = Env()
    ///     match env.get("HOME")
    ///         Some(home): println(home)
    ///         None: println("HOME not set")
    public fn get(name String) String?
        Some(miri_rt_env_get(name)) if miri_rt_env_has(name) == 1 else None

    /// Sets an environment variable for this process and its children.
    /// Returns Ok(true) if an existing value was replaced, Ok(false) if the
    /// variable was newly created.
    ///
    /// Example:
    ///     let env = Env()
    ///     match env.set("MY_VAR", "value")
    ///         Result.Ok(was_replaced): println(f"replaced: {was_replaced}")
    ///         Result.Err(e): println("error")
    public fn set(name String, value String) Result<bool, EnvError>
        let replaced = miri_rt_env_set(name, value)
        let status = miri_rt_env_status()
        match status
            0: Result.Ok(replaced == 1)
            1: Result.Err(EnvError.InvalidName(name))
            2: Result.Err(EnvError.InvalidValue(value))
            default: Result.Err(EnvError.Other(miri_rt_env_error_message()))

/// Command-line arguments passed to the program, excluding the program path.
/// Implements `Iterable<String>`, so `for arg in args` iterates the arguments.
///
/// Example:
///     let args = Args()
///     for arg in args
///         println(arg)
public class Args implements Iterable<String>

    runtime "core" fn miri_rt_args_count() int
    runtime "core" fn miri_rt_args_at(index int) String

    /// Returns the number of arguments, excluding the program path.
    ///
    /// Example:
    ///     let args = Args()
    ///     println(f"argument count: {args.length()}")
    public fn length() int
        return miri_rt_args_count()

    /// Returns the argument at the given 0-based index.
    /// An out-of-range index reports a bounds error and terminates the process,
    /// the same way array indexing does.
    ///
    /// Example:
    ///     let args = Args()
    ///     if args.length() > 0
    ///         println(args.element_at(0))
    public fn element_at(index int) String
        return miri_rt_args_at(index)

runtime "core" fn miri_rt_platform() String

/// Returns the name of the host platform, such as "macos", "linux" or "windows".
///
/// This is a free function rather than a capability method because it reports a
/// build-time constant of the runtime rather than mutable world state.
///
/// Example:
///     println(platform())
public fn platform() String
    return miri_rt_platform()

// SPDX-License-Identifier: Apache-2.0
// Copyright (c) Viacheslav Shynkarenko

// The floating-point types math is defined on. Each function below takes its
// arguments at one member and returns that member: `sin` of an `f32` is an
// `f32` on every target, as `f32::sin` in Rust and the WGSL overloads are.
// `abs`, `min` and `max` also take integers, typed at their argument.
public type Real is f16 or f32 or f64 or float

public intrinsic fn abs(x Real) Real
public intrinsic fn min(a Real, b Real) Real
public intrinsic fn max(a Real, b Real) Real
public intrinsic fn pow(base Real, exp Real) Real
public intrinsic fn sqrt(x Real) Real
public intrinsic fn floor(x Real) Real
public intrinsic fn ceil(x Real) Real
public intrinsic fn round(x Real) Real
public intrinsic fn sin(x Real) Real
public intrinsic fn cos(x Real) Real
public intrinsic fn tan(x Real) Real
public intrinsic fn log(x Real) Real
public intrinsic fn exp(x Real) Real
public intrinsic fn tanh(x Real) Real
public intrinsic fn exp2(x Real) Real
public intrinsic fn log2(x Real) Real
public intrinsic fn atan2(y Real, x Real) Real
public intrinsic fn fract(x Real) Real
public intrinsic fn clamp(x Real, lo Real, hi Real) Real
public intrinsic fn mix(a Real, b Real, t Real) Real
public intrinsic fn smoothstep(low Real, high Real, x Real) Real
public intrinsic fn step(edge Real, x Real) Real
public intrinsic fn sign(x Real) Real

// Logistic sigmoid, composed from `exp`. Usable on the CPU and inside GPU
// kernels (it lowers to a GPU-callable helper function).
public fn sigmoid(x Real) Real: 1.0 / (1.0 + exp(-x))

public const PI = 3.14159265358979323846
public const E = 2.71828182845904523536
public const INF = 1e309

// Deterministic integer hash (the MurmurHash3 `fmix32` finalizer). Maps any
// `u32` seed to a well-distributed `u32`; adjacent seeds avalanche to unrelated
// outputs. Portable across CPU and GPU because 32-bit integer multiply wraps
// identically on both. The all-zero seed is the one fixed point (maps to 0).
public fn hash_u32(seed u32) u32
    var h = seed * 374761393 as u32
    h = h ^ (h / 65536 as u32)
    h = h * 2246822519 as u32
    h = h ^ (h / 8192 as u32)
    h = h * 3266489917 as u32
    h = h ^ (h / 65536 as u32)
    return h

// Hash a 2D integer lattice point to a unit float in [0, 1). Coordinates are
// reinterpreted through `i32` so negative lattice points hash distinctly.
fn lattice_unit(xi float, yi float) float
    let kx = (xi as i32) as u32
    let ky = (yi as i32) as u32
    let key = kx * 1973 as u32 + ky * 9277 as u32 + 101 as u32
    return hash_u32(key) as float / 4294967295.0

// TODO: the noise functions below compute in `float` only. Taking `Real`
// needs a cast from an integer to a set-bounded type parameter (`h as T`),
// which the checker refuses ("cannot cast to non-numeric type 'T'").
//
// 2D value noise in [0, 1): smoothstep-weighted bilinear blend of the four
// hashed integer-lattice corners around (x, y). Deterministic and continuous.
public fn value_noise(x float, y float) float
    let xi = floor(x)
    let yi = floor(y)
    let xf = x - xi
    let yf = y - yi
    let c00 = lattice_unit(xi, yi)
    let c10 = lattice_unit(xi + 1.0, yi)
    let c01 = lattice_unit(xi, yi + 1.0)
    let c11 = lattice_unit(xi + 1.0, yi + 1.0)
    let u = xf * xf * (3.0 - 2.0 * xf)
    let v = yf * yf * (3.0 - 2.0 * yf)
    let a = c00 + (c10 - c00) * u
    let b = c01 + (c11 - c01) * u
    return a + (b - a) * v

// Fractional Brownian motion: two octaves of value noise at halving amplitude.
public fn fbm(x float, y float) float
    return value_noise(x, y) * 0.5 + value_noise(x * 2.0, y * 2.0) * 0.25

// Divergence-free curl field of an `fbm` potential, for advecting particles:
// curl = (dP/dy, -dP/dx), returned component-wise (vector types land in DP5).
public fn curl_noise_x(x float, y float) float
    let eps = 0.01
    return (fbm(x, y + eps) - fbm(x, y - eps)) / (2.0 * eps)

public fn curl_noise_y(x float, y float) float
    let eps = 0.01
    return (fbm(x - eps, y) - fbm(x + eps, y)) / (2.0 * eps)

