use system.os
use system.fs
use system.collections.list
use system.collections.map

// Bounds of a signed 64-bit total. Miri's `int` wraps silently on overflow, so
// each addition is checked against these bounds before it is made.
const MAX_TOTAL = 9223372036854775807
const MIN_TOTAL = -9223372036854775808

fn read_input(path String) String
    let fs = Fs()
    match fs.read_file(path)
        Result.Ok(text):
            return text
        Result.Err(e):
            panic(f"cannot read {path}")
    return ""

// Splits a line on spaces, dropping empty pieces. A carriage return that ends
// a CRLF line is removed first.
fn tokens(line String) [String]
    var text = line
    if text.ends_with("\r")
        text = text.substring(0, text.length() - 1)
    let parts = List<String>()
    for piece in text.split(" ")
        if piece.size() > 0
            parts.push(piece)
    return parts

// Adds a value to a key's running total. A key whose running total would leave
// the signed 64-bit range is marked as overflowed and takes no further values.
fn record(totals Map<String, int>, overflowed Map<String, bool>, key String, value int)
    if overflowed.contains_key(key)
        return
    match totals.get(key)
        Some(total):
            if (value > 0 and total > MAX_TOTAL - value) or (value < 0 and total < MIN_TOTAL - value)
                overflowed.set(key, true)
            else
                totals.set(key, total + value)
        None:
            totals.set(key, value)

fn main()
    let args = Args()
    if args.length() == 0
        panic("usage: keyed-totals FILE")
    let lines = read_input(args.element_at(0)).split("\n")
    let totals = Map<String, int>()
    let overflowed = Map<String, bool>()

    // Records run up to the first blank line.
    var index = 0
    while index < lines.length()
        let line = lines[index]
        index = index + 1
        let parts = tokens(line)
        if parts.length() == 0
            break
        if parts.length() != 2
            panic(f"malformed record: {line}")
        match parts[1].to_int()
            Some(value):
                record(totals, overflowed, parts[0], value)
            None:
                panic(f"malformed value: {line}")

    // Queries follow; blank lines between them are skipped.
    while index < lines.length()
        let parts = tokens(lines[index])
        index = index + 1
        if parts.length() == 0
            continue
        let key = parts[0]
        if overflowed.contains_key(key)
            println(f"{key}=overflow")
        else
            match totals.get(key)
                Some(total):
                    println(f"{key}={total}")
                None:
                    println(f"{key}=absent")

